async function saveGuildMember(env,guildId,payload={},authToken){const ctx=await requireGuildOperate(env,authToken,guildId), nickname=String(payload.nickname||"").trim();if(!nickname)throw new Error("닉네임을 입력하세요.");if(await first(env.DB,"SELECT 1 FROM members WHERE guild_id=? AND nickname=? AND status='활성'",String(guildId),nickname))throw new Error("같은 닉네임의 활성 길드원이 이미 있습니다.");const role=assertCanAssignRole(ctx,String(payload.role||"길드원")),memberId=uid("member"),pin=randomPin(),hash=await sha256Hex(`${memberId}:${pin}`);await run(env.DB,"INSERT INTO members(member_id,guild_id,nickname,role,alliance_role,joined_at,status,note,web_pin_hash,web_access_enabled) VALUES(?,?,?,?,?,?,'활성',?,?,1)",memberId,String(guildId),nickname,role,"",nowIso(),String(payload.note||""),hash);return {ok:true,message:"길드원을 등록했습니다. 웹 로그인 PIN이 함께 발급되었습니다.",member_id:memberId,access_pin:pin,role};}
async function resetMemberWebPin(env,guildId,memberId,authToken){const ctx=await requireGuildOperate(env,authToken,guildId),m=await first(env.DB,"SELECT * FROM members WHERE guild_id=? AND member_id=?",String(guildId),String(memberId));if(!m)throw new Error("길드원을 찾을 수 없습니다.");assertCanManageMember(ctx,m.role);const pin=randomPin(),hash=await sha256Hex(`${m.member_id}:${pin}`);await run(env.DB,"UPDATE members SET web_pin_hash=?,web_access_enabled=1 WHERE member_id=?",hash,String(memberId));return {ok:true,message:"웹 로그인 PIN을 발급했습니다.",pin,member_id:String(memberId)};}
async function updateGuildMemberRole(env,guildId,memberId,newRole,authToken){const ctx=await requireGuildOperate(env,authToken,guildId),m=await first(env.DB,"SELECT * FROM members WHERE guild_id=? AND member_id=?",String(guildId),String(memberId));if(!m)throw new Error("길드원을 찾을 수 없습니다.");assertCanManageMember(ctx,m.role);const role=assertCanAssignRole(ctx,newRole);await run(env.DB,"UPDATE members SET role=? WHERE member_id=?",role,String(memberId));return {ok:true,message:`직급을 ${role}(으)로 변경했습니다.`,role};}
async function updateMemberAllianceRole(env,guildId,memberId,newRole,authToken){const g=await guildMeta(env,guildId,true),ctx=await requireLogin(env,authToken);if(!ctx.is_superadmin&&(String(ctx.alliance_id)!==String(g.alliance_id)||String(ctx.alliance_role)!=="연합장"))throw new Error("연합장 권한이 필요합니다.");const raw=String(newRole||"").trim(),role=normalizeAllianceRole(raw);if(raw&&!role)throw new Error("연합 권한은 연합장/연합운영진/없음만 가능합니다.");const m=await first(env.DB,"SELECT 1 FROM members WHERE guild_id=? AND member_id=?",String(guildId),String(memberId));if(!m)throw new Error("길드원을 찾을 수 없습니다.");await run(env.DB,"UPDATE members SET alliance_role=? WHERE member_id=?",role,String(memberId));return {ok:true,message:role?`연합 권한을 ${role}(으)로 변경했습니다.`:"연합 권한을 해제했습니다.",alliance_role:role};}

async function saveGuildLoot(env,guildId,payload={},authToken){await requireGuildOperate(env,authToken,guildId);const item=String(payload.item_name||"").trim(),qty=Math.max(1,Number(payload.quantity||1)),status=String(payload.status||"보유"),sale=Math.max(0,Number(payload.sale_amount||0));if(!item)throw new Error("아이템명을 입력하세요.");if(!["보유","판매완료","지급완료"].includes(status))throw new Error("아이템 상태가 올바르지 않습니다.");await run(env.DB,"INSERT INTO loot(loot_id,guild_id,raid_id,item_name,quantity,status,winner_member_id,sale_amount,fund_rate,fund_amount,guild_support_amount,distribution_pool,completed_at,note,created_at,source) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",uid("loot"),String(guildId),String(payload.raid_id||""),item,qty,status,String(payload.winner_member_id||""),sale||null,null,null,null,null,(status==="판매완료"||status==="지급완료")?nowIso():"",String(payload.note||""),nowIso(),String(payload.source||"web"));return {ok:true,message:"아이템을 등록했습니다."};}
async function markGuildLootSold(env,guildId,lootId,saleAmount,authToken){await requireGuildOperate(env,authToken,guildId);const amount=Math.max(0,Number(saleAmount||0));if(!(amount>0))throw new Error("판매금액을 입력하세요.");const l=await first(env.DB,"SELECT 1 FROM loot WHERE guild_id=? AND loot_id=?",String(guildId),String(lootId));if(!l)throw new Error("아이템을 찾을 수 없습니다.");await run(env.DB,"UPDATE loot SET status='판매완료',sale_amount=?,completed_at=? WHERE loot_id=?",amount,nowIso(),String(lootId));return {ok:true,message:"판매완료로 변경했습니다."};}
async function createDistributionRequest(env,guildId,payload={},authToken){const ctx=await requireGuildMember(env,authToken,guildId);if(!payload.loot_id)throw new Error("아이템을 선택하세요.");let memberId=String(payload.member_id||"");if(!ctx.is_superadmin&&Number(ctx.level)<20)memberId=String(ctx.member_id||"");if(!memberId)throw new Error("신청 길드원을 확인할 수 없습니다.");await run(env.DB,"INSERT INTO distribution_requests(request_id,guild_id,loot_id,member_id,request_type,priority,status,requested_at,note) VALUES(?,?,?,?,?,?,'신청',?,?)",uid("req"),String(guildId),String(payload.loot_id),memberId,String(payload.request_type||"희망"),Number(payload.priority||0),nowIso(),String(payload.note||""));return {ok:true,message:"분배 희망 신청을 등록했습니다."};}
async function addFundTransaction(env,guildId,payload={},authToken){await requireGuildOperate(env,authToken,guildId);const amount=Math.abs(Number(payload.amount||0));if(!amount)throw new Error("금액을 입력하세요.");const type=String(payload.type||"other_income"),signed=type==="expense"?-amount:amount,bal=await first(env.DB,"SELECT COALESCE(SUM(amount_signed),0) balance FROM fund_ledger WHERE guild_id=?",String(guildId)),after=Number(bal?.balance||0)+signed;await run(env.DB,"INSERT INTO fund_ledger(txn_id,guild_id,occurred_at,type,amount_signed,balance_after,reference_type,reference_id,member_id,memo,created_by,source,note) VALUES(?,?,?,?,?,?, 'manual','','',?,'web','web','')",uid("txn"),String(guildId),nowIso(),type==="expense"?"expense":"other_income",signed,after,String(payload.memo||""));return {ok:true,message:"금고에 반영했습니다.",balance:after};}

async function getGuildStats(env,guildId,startDate,endDate){
  const g=await guildMeta(env,guildId), start=parseLocalDateTime(`${startDate} 00:00`), end=parseLocalDateTime(`${endDate} 23:59`);if(!start||!end)throw new Error("기간 형식이 올바르지 않습니다.");
  const events=await all(env.DB,"SELECT * FROM boss_events WHERE alliance_id=? AND cut_at>=? AND cut_at<=? AND (boss_scope='WORLD' OR server_id=?)",g.alliance_id,start.toISOString(),end.toISOString(),g.server_id||"");
  if(!events.length)return {total_raids:0,ranking:[]};
  const ids=events.map(x=>x.event_id); const ph=ids.map(()=>"?").join(",");
  const rows=await all(env.DB,`SELECT member_id_at_event member_id,game_nickname_at_event nickname,COUNT(*) count FROM boss_attendance WHERE guild_id_at_event=? AND attended=1 AND event_id IN (${ph}) GROUP BY member_id_at_event,game_nickname_at_event`,String(guildId),...ids);
  const total=events.length;return {total_raids:total,ranking:rows.map(x=>({member_id:x.member_id,nickname:x.nickname||x.member_id,count:Number(x.count||0),rate:total?Math.round(Number(x.count||0)/total*1000)/10:0})).sort((a,b)=>b.count-a.count||String(a.nickname).localeCompare(String(b.nickname)))};
}

async function saveAllianceBoss(env,allianceId,payload={},authToken){
  await requireAllianceOperate(env,authToken,allianceId);const name=String(payload.boss_name||"").trim(),type=String(payload.boss_type||"cooldown"),scope=String(payload.boss_scope||"WORLD").toUpperCase()==="SERVER"?"SERVER":"WORLD";if(!name)throw new Error("보스명을 입력하세요.");if(!["cooldown","fixed","weekly"].includes(type))throw new Error("보스 유형이 올바르지 않습니다.");let sid="";if(scope==="SERVER"){sid=String(payload.server_id||"").trim();if(!await serverMeta(env,allianceId,sid))throw new Error("서버를 선택하세요.");}if(await first(env.DB,"SELECT 1 FROM bosses WHERE alliance_id=? AND boss_name=? AND boss_scope=? AND server_id=? AND enabled=1",String(allianceId),name,scope,sid))throw new Error("같은 범위에 이미 등록된 보스명입니다.");let resp=null,fixed="";if(type==="cooldown"){const h=Number(payload.time_value||0);if(!(h>0))throw new Error("쿨타임 시간을 입력하세요.");resp=Math.round(h*60);}else if(type==="fixed"){const t=fixedTimes(payload.time_value);if(!t.length)throw new Error("고정 젠시간을 입력하세요. 예: 06:00,18:00");fixed=t.join(",");}else{const w=parseWeekly(payload.time_value);if(!w)throw new Error("요일과 시간을 선택하세요.");fixed=`${w.code}@${w.time}`;}const id=uid("boss"),a=await allianceMeta(env,allianceId),now=nowIso();await run(env.DB,"INSERT INTO bosses(boss_id,alliance_id,game_id,boss_name,boss_type,boss_scope,server_id,respawn_minutes,fixed_times,enabled,note,notify_enabled,alert_10m,alert_5m,alert_1m,alert_spawn,attendance_enabled,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,1,?,?,?,?,?,?,?,?,?)",id,String(allianceId),a.game_id||"eclipse",name,type,scope,sid,resp,fixed,String(payload.note||""),bint(payload.notify_enabled,true),bint(payload.alert_10m,true),bint(payload.alert_5m,true),bint(payload.alert_1m,true),bint(payload.alert_spawn,true),bint(payload.attendance_enabled,true),now,now);return {ok:true,message:"보스를 등록했습니다.",boss_id:id};
}
async function disableAllianceBoss(env,allianceId,bossId,authToken){await requireAllianceOperate(env,authToken,allianceId);const b=await first(env.DB,"SELECT * FROM bosses WHERE alliance_id=? AND boss_id=?",String(allianceId),String(bossId));if(!b)throw new Error("보스를 찾을 수 없습니다.");await env.DB.batch([env.DB.prepare("UPDATE bosses SET enabled=0,updated_at=? WHERE boss_id=?").bind(nowIso(),String(bossId)),env.DB.prepare("UPDATE boss_state SET status='삭제',updated_at=? WHERE alliance_id=? AND boss_id=?").bind(nowIso(),String(allianceId),String(bossId))]);return {ok:true,message:`${b.boss_name} 삭제 완료 · 과거 기록은 유지됩니다.`,boss_id:String(bossId),boss_name:b.boss_name};}
async function registerAllianceBossCut(env,allianceId,bossId,cutAtValue,registeredBy,source,authToken){await requireAllianceOperate(env,authToken,allianceId);const b=await first(env.DB,"SELECT * FROM bosses WHERE alliance_id=? AND boss_id=? AND enabled=1",String(allianceId),String(bossId));if(!b)throw new Error("보스를 찾을 수 없습니다.");if(b.boss_type!=="cooldown")throw new Error("시간표형 보스는 컷 등록이 필요하지 않습니다.");let cut=cutAtValue?parseLocalDateTime(cutAtValue):new Date();if(!cut)throw new Error("컷 시각이 올바르지 않습니다.");if(cutAtValue&&/^\d{2}:\d{2}$/.test(String(cutAtValue).trim())&&cut.getTime()>Date.now()+300000)cut=new Date(cut.getTime()-86400000);if(boolVal(b.attendance_enabled,true)&&await first(env.DB,"SELECT 1 FROM boss_events WHERE alliance_id=? AND boss_id=? AND attendance_status='open'",String(allianceId),String(bossId)))throw new Error("이미 출석 진행 중인 보스입니다.");const next=new Date(cut.getTime()+Number(b.respawn_minutes||0)*60000),now=nowIso();await run(env.DB,"INSERT INTO boss_state(alliance_id,boss_id,boss_scope,server_id,last_kill_at,next_spawn_at,status,registered_by_discord_user_id,source,updated_at,note) VALUES(?,?,?,?,?,?, '대기',?,?,?,'') ON CONFLICT(alliance_id,boss_id) DO UPDATE SET boss_scope=excluded.boss_scope,server_id=excluded.server_id,last_kill_at=excluded.last_kill_at,next_spawn_at=excluded.next_spawn_at,status='대기',registered_by_discord_user_id=excluded.registered_by_discord_user_id,source=excluded.source,updated_at=excluded.updated_at",String(allianceId),String(bossId),b.boss_scope||"WORLD",b.server_id||"",cut.toISOString(),next.toISOString(),String(registeredBy||""),String(source||"web"),now);let eventId="";if(boolVal(b.attendance_enabled,true)){eventId=uid("event");const closes=new Date(Date.now()+10*60000);await run(env.DB,"INSERT INTO boss_events(event_id,alliance_id,boss_id,boss_name,boss_scope,server_id,event_type,cut_at,next_spawn_at,attendance_opened_at,attendance_closes_at,attendance_status,registered_by_discord_user_id,source,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,'open',?,?,?,?)",eventId,String(allianceId),String(bossId),b.boss_name,b.boss_scope||"WORLD",b.server_id||"",cutAtValue?"past_cut":"cut",cut.toISOString(),next.toISOString(),now,closes.toISOString(),String(registeredBy||""),String(source||"web"),now,now);}return {ok:true,message:`${b.boss_name} 컷 등록 완료${eventId?" · 출석 OPEN":""}`,event_id:eventId,state:{boss_name:b.boss_name,last_kill_at:formatKst(cut),next_spawn_at:formatKst(next),status:"대기"}};}
async function setAllianceBossSpawn(env,allianceId,bossId,spawnAtValue,registeredBy,source,authToken){await requireAllianceOperate(env,authToken,allianceId);const b=await first(env.DB,"SELECT * FROM bosses WHERE alliance_id=? AND boss_id=? AND enabled=1",String(allianceId),String(bossId));if(!b)throw new Error("보스를 찾을 수 없습니다.");const now=nowIso();if(spawnAtValue===null||String(spawnAtValue||"").trim()===""){await run(env.DB,"INSERT INTO boss_state(alliance_id,boss_id,boss_scope,server_id,next_spawn_at,status,registered_by_discord_user_id,source,updated_at,note) VALUES(?,?,?,?, '','미등록',?,?,?,'') ON CONFLICT(alliance_id,boss_id) DO UPDATE SET next_spawn_at='',status='미등록',registered_by_discord_user_id=excluded.registered_by_discord_user_id,source=excluded.source,updated_at=excluded.updated_at",String(allianceId),String(bossId),b.boss_scope||"WORLD",b.server_id||"",String(registeredBy||""),String(source||"web"),now);return {ok:true,message:`${b.boss_name} 젠 시각을 제거했습니다.`,next_spawn_at:""};}let spawn=parseLocalDateTime(spawnAtValue);if(!spawn)throw new Error("젠 시각이 올바르지 않습니다.");if(/^\d{2}:\d{2}$/.test(String(spawnAtValue).trim())&&spawn.getTime()<Date.now()-60000)spawn=new Date(spawn.getTime()+86400000);await run(env.DB,"INSERT INTO boss_state(alliance_id,boss_id,boss_scope,server_id,next_spawn_at,status,registered_by_discord_user_id,source,updated_at,note) VALUES(?,?,?,?,?,'대기',?,?,?,'') ON CONFLICT(alliance_id,boss_id) DO UPDATE SET boss_scope=excluded.boss_scope,server_id=excluded.server_id,next_spawn_at=excluded.next_spawn_at,status='대기',registered_by_discord_user_id=excluded.registered_by_discord_user_id,source=excluded.source,updated_at=excluded.updated_at",String(allianceId),String(bossId),b.boss_scope||"WORLD",b.server_id||"",spawn.toISOString(),String(registeredBy||""),String(source||"web"),now);return {ok:true,message:`${b.boss_name} 젠 시각을 변경했습니다.`,next_spawn_at:formatKst(spawn)};}
async function attendanceSummary(env,event){const rows=await all(env.DB,"SELECT * FROM boss_attendance WHERE event_id=? AND attended=1 ORDER BY guild_name_at_event,game_nickname_at_event",event.event_id);const names=rows.map(x=>x.game_nickname_at_event).filter(Boolean);return `📋 ${event.boss_name} 출석 종료\n참여 ${names.length}명${names.length?"\n"+names.join(" · "):""}`;}
async function closeBossAttendance(env,allianceId,eventId,source,authToken){await requireAllianceOperate(env,authToken,allianceId);const e=await first(env.DB,"SELECT * FROM boss_events WHERE alliance_id=? AND event_id=?",String(allianceId),String(eventId));if(!e)throw new Error("보스 이벤트를 찾을 수 없습니다.");if(e.attendance_status!=="open")return {ok:true,message:"이미 종료된 출석입니다."};const now=nowIso();await run(env.DB,"UPDATE boss_events SET attendance_status='closed',attendance_closed_at=?,closed_reason='manual',updated_at=?,source=? WHERE event_id=?",now,now,String(source||e.source||"web"),String(eventId));const summary=await attendanceSummary(env,e),srv=e.server_id?await serverMeta(env,allianceId,e.server_id):null;await run(env.DB,"INSERT INTO attendance_result_queue(result_id,alliance_id,event_id,boss_id,boss_name,boss_scope,server_id,server_name,message,discord_status,kakao_status,created_at,discord_message_id,discord_channel_id,note) VALUES(?,?,?,?,?,?,?,?,?,'queued','queued',?,'','','')",uid("result"),String(allianceId),e.event_id,e.boss_id,e.boss_name,e.boss_scope||"WORLD",e.server_id||"",srv?.server_name||"",summary,now);return {ok:true,message:"출석을 종료했습니다."};}

async function processScheduled(env){
  await ensureBootstrap(env);const now=new Date(),nowS=now.toISOString();
  const expired=await all(env.DB,"SELECT * FROM boss_events WHERE attendance_status='open' AND attendance_closes_at<>'' AND attendance_closes_at<=?",nowS);
  for(const e of expired){await run(env.DB,"UPDATE boss_events SET attendance_status='closed',attendance_closed_at=?,closed_reason='auto_10m',updated_at=? WHERE event_id=? AND attendance_status='open'",nowS,nowS,e.event_id);const summary=await attendanceSummary(env,e),srv=e.server_id?await serverMeta(env,e.alliance_id,e.server_id):null;await run(env.DB,"INSERT OR IGNORE INTO attendance_result_queue(result_id,alliance_id,event_id,boss_id,boss_name,boss_scope,server_id,server_name,message,discord_status,kakao_status,created_at,discord_message_id,discord_channel_id,note) VALUES(?,?,?,?,?,?,?,?,?,'queued','queued',?,'','','auto close')",`result_${e.event_id}`,e.alliance_id,e.event_id,e.boss_id,e.boss_name,e.boss_scope||"WORLD",e.server_id||"",srv?.server_name||"",summary,nowS);}
  const bosses=await all(env.DB,"SELECT b.*,a.discord_alert_channel_id FROM bosses b JOIN alliances a ON a.alliance_id=b.alliance_id WHERE b.enabled=1 AND b.notify_enabled=1 AND a.status='active'");
  for(const b of bosses){let spawns=[];if(b.boss_type==="cooldown"){const st=await first(env.DB,"SELECT next_spawn_at FROM boss_state WHERE alliance_id=? AND boss_id=?",b.alliance_id,b.boss_id);if(st?.next_spawn_at)spawns=[new Date(st.next_spawn_at)];}else spawns=scheduledCandidates(b,now);for(const spawn of spawns){if(!spawn||Number.isNaN(spawn.getTime()))continue;for(const a of [{type:"10m",mins:10,on:boolVal(b.alert_10m,true)},{type:"5m",mins:5,on:boolVal(b.alert_5m,true)},{type:"1m",mins:1,on:boolVal(b.alert_1m,true)},{type:"spawn",mins:0,on:boolVal(b.alert_spawn,true)}]){if(!a.on)continue;const due=new Date(spawn.getTime()-a.mins*60000),lag=now.getTime()-due.getTime();if(lag<0||lag>=120000)continue;const srv=b.server_id?await serverMeta(env,b.alliance_id,b.server_id):null,t=formatKst(spawn,false).slice(-5),msg=a.type==="spawn"?`🚨 [${b.boss_name}] 젠 시간입니다! (${t} 젠)`:`⏰ [${b.boss_name}] 젠 ${a.mins}분 전입니다. (${t} 젠)`;await run(env.DB,"INSERT OR IGNORE INTO boss_alert_queue(alert_id,alliance_id,boss_id,boss_name,boss_scope,server_id,server_name,spawn_at,alert_type,due_at,status,discord_status,kakao_status,message,created_at,target,discord_channel_id,discord_channel_ids,note) VALUES(?,?,?,?,?,?,?,?,?,?,'queued','queued','queued',?,?,'alliance',?,'','')",uid("alert"),b.alliance_id,b.boss_id,b.boss_name,b.boss_scope||"WORLD",b.server_id||"",srv?.server_name||"",spawn.toISOString(),a.type,due.toISOString(),msg,nowS,b.discord_alert_channel_id||"");}}}
  await run(env.DB,"DELETE FROM sessions WHERE expires_at<=?",nowS);
  return {ok:true,attendance_closed:expired.length};
}

const RPC = {
  webLogin, webWhoAmI, webLogout,
  getAllianceHomeData, getGuildAppData, getAdminStructure,
  createAllianceWorkspace, renameAlliance, deactivateAlliance, restoreAlliance, deleteAlliancePermanently,
  createGuildWorkspace, renameGuild, updateGuildServer, deactivateGuild, restoreGuild, deleteGuildPermanently,
  saveAllianceNotice, saveGuildNotice,
  saveGuildMember, resetMemberWebPin, updateGuildMemberRole, updateMemberAllianceRole,
  saveGuildLoot, markGuildLootSold, createDistributionRequest, addFundTransaction, getGuildStats,
  saveAllianceBoss, disableAllianceBoss, registerAllianceBossCut, setAllianceBossSpawn, closeBossAttendance
};

async function handleRpc(request, env){
  let body;try{body=await request.json()}catch{throw new Error("JSON 요청 형식이 올바르지 않습니다.");}
  const method=String(body?.method||""),args=Array.isArray(body?.args)?body.args:[];
  const fn=RPC[method];if(!fn)throw new Error("지원하지 않는 RPC: "+method);
  return await fn(env,...args);
}

async function handleBotApi(request,env){
  /* V6 공통 봇 API 자리. 현재 웹 전환 먼저 사용하며, Discord/Kakao는 이 엔드포인트에 바로 연결한다. */
  const key=request.headers.get("Authorization")?.replace(/^Bearer\s+/i,"")||"";
  if(env.BOT_API_KEY&&key!==String(env.BOT_API_KEY))return json({ok:false,error:"인증 실패"},401);
  let body={};try{body=await request.json()}catch{}
  const action=String(body.action||"");
  if(action==="health")return json({ok:true,data:{version:APP_VERSION,engine:"Cloudflare Worker + D1"}});
  if(action==="config"){
    const aid=String(body.alliance_id||"alliance_001");
    try{return json({ok:true,data:await getAllianceHomeData(env,aid)})}catch(e){return json({ok:false,error:errorMessage(e)},400)}
  }
  return json({ok:false,error:"V6 봇 API 액션은 다음 빌드에서 연결됩니다: "+action},400);
}


export default {
  async fetch(request, env, ctx) {
    try {
      const url = new URL(request.url);
      if (request.method === "GET" && url.pathname === "/health") {
        return json({ok:true,version:APP_VERSION,engine:"Cloudflare Worker + D1"});
      }
      if (request.method === "GET" && (url.pathname === "/" || url.pathname === "/index.html")) {
        await ensureBootstrap(env);
        return new Response(APP_HTML, {
          headers:{"Content-Type":"text/html; charset=utf-8","Cache-Control":"no-store"}
        });
      }
      if (request.method === "POST" && url.pathname === "/rpc") {
        try {
          const data = await handleRpc(request, env);
          return json({ok:true,data});
        } catch (e) {
          return json({ok:false,error:errorMessage(e)},400);
        }
      }
      if (request.method === "POST" && url.pathname === "/api/bot") {
        return await handleBotApi(request, env);
      }
      return new Response("Not Found", {status:404});
    } catch (e) {
      return json({ok:false,error:errorMessage(e)},500);
    }
  },
  async scheduled(event, env, ctx) {
    ctx.waitUntil(processScheduled(env));
  }
};
